def pi(n):
    """Calculates the prime counting function pi(n)."""
    primes = []
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for p in range(2, n + 1):
        if is_prime[p]:
            primes.append(p)
            for i in range(p * p, n + 1, p):
                is_prime[i] = False
    return len(primes)

def v_p(n_fact, p):
    """Calculates the exponent of prime p in n! (Legendre's formula)."""
    count = 0
    i = p
    while i <= n_fact:
        count += n_fact // i
        i *= p
    return count

def calculate_omega(n):
    if n < 1:
        return 0

    # Primes <= n
    primes_le_n = [i for i in range(2, n + 1) if all(i % j != 0 for j in range(2, int(i**0.5) + 1))]

    omega_count = 0

    for p in primes_le_n:
        vp_n_fact = v_p(n, p)

        if p == 7:
            vp_2023 = 1
            if vp_n_fact > vp_2023:
                omega_count += 1
        elif p == 17:
            vp_2023 = 2
            if vp_n_fact > vp_2023:
                omega_count += 1
        else:
            # For all other primes p, v_p(2023) = 0, so p always contributes if p <= n
            omega_count += 1

    return omega_count

